INTO v_docket_id_str
FROM JISREM.CJIS_DOCKET
WHERE row_state = 'BEFORE'
AND change_action = 'DELETE'
AND CHARGE_ID = 1221572
AND cleanup_id = '004d770d-a1f5-4bcc-9b4d-ec26acbc91b4';

